// Mehlman Microbiology Assessment #1 - Virology (full coverage, all 20 questions)
const microQuestions = [
  // ===== MICRO: Herpesviridae =====
  { id: "mic1", category: "Herpesviridae", q: "22F with a painful vesicular eruption on her labium majus (burning/stinging pain), fever 101F, left inguinal lymphadenopathy. Best description of the viral etiology (genome / envelope / shape)?", a: "DNA; enveloped; linear. This is acute genital herpes (HSV1 or HSV2 - the HSV1=oral / HSV2=genital propensity has considerable overlap). Primary (first-time) infection is often more severe than flareups, with fever and regional adenopathy; systemic symptoms (headache, fever, myalgia, backache) occur in ~70% of women and ~40% of men. Herpesviridae are double-stranded LINEAR enveloped DNA viruses - contrast hepatitis B, which is double-stranded CIRCULAR enveloped DNA. The USMLE really likes this distinction: herpes = DNA, enveloped, linear; Hep B = DNA, enveloped, circular." },
  // ===== MICRO: Poxvirus =====
  { id: "mic2", category: "Poxvirus", q: "9M with these lesions on his trunk after a one-month summer camp. What might be seen under light microscopy on biopsy of a lesion?", a: "Large intracytoplasmic, basophilic inclusions - molluscum bodies within keratinocytes. This is molluscum contagiosum, caused by poxvirus: shiny, dome-shaped, peach-colored papules with central umbilication, usually in children; classically spread by shared towels (public pools) and contaminated fomites; lesions appear 2-6 weeks after exposure and self-resolve over months to a few years. Distractors: 'multinucleated T lymphocytes' = Warthin-Finkeldey cells (measles prodrome, tonsils); 'intranuclear inclusions' = Cowdry bodies (herpesviridae); 'small/medium lymphocytes with cerebriform nuclei' = mycosis fungoides / Sezary syndrome (HTLV).", img: "/qimg/micro/molluscum.webp", alt: "Shiny, dome-shaped, flesh-colored papules with central umbilication on a child's trunk - molluscum contagiosum" },
  // ===== MICRO: GI Viruses =====
  { id: "mic3", category: "GI Viruses", q: "3M, unvaccinated, with 2 days of severe watery diarrhea; pale with sunken orbits. Best description of the most likely viral etiology (genome / envelope / strandedness / segmentation)?", a: "RNA; non-enveloped; double-stranded; segmented - rotavirus, the world's leading cause of severe dehydrating diarrhea in children under 5 (11 dsRNA segments). Onset ~2 days after fecal-oral exposure; vomiting + watery diarrhea last 3-8 days. Oral vaccine at 2, 4, 6 months. USMLE: young child + watery diarrhea with no vaccination history mentioned = rotavirus. If the child was vaccinated or parents/siblings are simultaneously sick, think Norwalk virus (norovirus) - second-leading cause in young children, and common in older children and adults." },
  // ===== MICRO: Viral Exanthems =====
  { id: "mic4", category: "Viral Exanthems", q: "6F with fever 101F, malaise, anorexia x2 days; as the fever abates, a maculopapular rash starts on her face and spreads downward over her whole body for 3 days; tender suboccipital and postauricular lymphadenopathy. Diagnosis?", a: "Rubella (German measles, three-day measles). Peak age 5-9; 3-day prodrome; rash starts at the head and descends as the fever abates; suboccipital/postauricular lymphadenopathy is exceedingly HY; adults may get arthritis. MMR (live-attenuated) at 12-15 months and 4-6 years - MMR and varicella are the only live-attenuated vaccines OK in HIV (CD4 >200). Congenital rubella (first-trimester infection of a non-immune mother): neonatal deafness, meningoencephalitis, cataracts, PDA (exceedingly HY). Compare: rubeola (measles) = 3Cs (cough, coryza, conjunctivitis) + Koplik spots; mumps = parotitis/orchitis/meningitis, no rash; roseola (HHV6) = high spiking fever 3-5 days, then rash as the fever breaks; fifth disease (parvovirus B19) = slapped-cheek rash, no longer infectious once the rash appears, can cause aplastic crisis (especially sickle cell), lacy rash/arthritis in adults." },
  // ===== MICRO: Adenovirus =====
  { id: "mic5", category: "Adenovirus", q: "4M in daycare with itchy, watery eyes and injected conjunctivae. The most likely causative virus is also known to cause what?", a: "Hemorrhagic cystitis. Adenovirus is the most common cause of viral conjunctivitis (and keratoconjunctivitis); it also causes hemorrhagic cystitis (hematuria, dysuria, frequency, urgency, resolving within ~2 weeks). Not believed to cause cancers in humans (though it can transform mammalian cells in vitro). DM type I viral precipitators in susceptible HLA haplotypes: coxsackie B (most common), rotavirus, mumps, CMV." },
  // ===== MICRO: Polyomavirus =====
  { id: "mic6", category: "Polyomavirus", q: "40M IV drug user with a first-time focal seizure; 2 days of headache, confusion, sensory aphasia, right hemiparesis; CD4 135, on HAART + TMP-SMX; CSF detects a DNA virus. Most likely finding?", a: "Multifocal subcortical hyperintense lesions on T2-weighted MRI - progressive multifocal leukoencephalopathy (PML) from JC polyomavirus. PML destroys oligodendrocytes and their myelin; classically HIV with CD4 <300; presents with coordination disturbance, cognitive defects, limb paresis; T2-hyperintense / T1-hypointense lesions (pedantic but HY). Distractors: 'ring-enhancing lesions on T1 with gadolinium' = toxoplasmosis - and because TMP-SMX is toxo (and Pneumocystis) prophylaxis, toxo is an absolute wrong answer on the USMLE in a patient taking it; 'striatum/thalamus T2 hyperintensities' = Creutzfeldt-Jakob (prion); 'temporal lobe atrophy/blurring' = temporal lobe epilepsy." },
  { id: "mic7", category: "Polyomavirus", q: "A researcher studies a virus associated with renal transplants: organ tropism largely limited to the reno-urinary tract, causing a tubulointerstitial inflammatory response, ureteral stenosis, and hemorrhagic cystitis. Best description of the virus (genome / envelope / shape)?", a: "DNA; non-enveloped; circular - BK polyomavirus, which causes severe nephropathy, ureteral stenosis, and hemorrhagic cystitis in renal transplant recipients (tubulointerstitial inflammation similar to acute rejection). ~75% of adults are seropositive but asymptomatic. HY contrast: CMV remains the most common opportunistic pathogen overall in organ transplant recipients, but CMV can hit almost any organ system, whereas BK is largely limited to the reno-urinary tract." },
  // ===== MICRO: HTLV =====
  { id: "mic8", category: "HTLV", q: "42M with 2 years of a diffusely erythematous scaly rash on trunk/extremities, intensely pruritic; erythrodermic patches; WBC 23,000 with ~90% lymphocytes; smear shows large lymphoid cells with prominent nuclear indentations and grooving; TEM shows cerebriform nuclei; marrow unremarkable. Diagnosis?", a: "Sezary syndrome - the leukemic extension of mycosis fungoides: a cutaneous T-cell non-Hodgkin lymphoma with 'fiery red' erythroderma and Sezary cells (cerebriform nuclei) in skin, nodes, and peripheral blood. MF is the purely cutaneous form; SS is the advancing leukemic phase. Caused by HTLV, which is endemic to Japan (with increased adult T-cell leukemia/lymphoma) and associated with IV drug use (HTLV and HIV are both retroviruses). Distractors: Kaposi sarcoma = HHV8 neoplasm of lymphatic endothelium, violaceous macules -> plaques/papules/nodules, classic in AIDS and elderly Ashkenazi men; lichen planus = 6 Ps (purple, pruritic, polygonal, planar, papules, plaques), associated with hepatitis C." },
  // ===== MICRO: CNS Viruses =====
  { id: "mic9", category: "CNS Viruses", q: "18M with fever, increasing confusion, aphasia; CT head unremarkable; EEG shows temporal complexes/slowing; CSF: glucose 70 (nl 50-80), protein 75 (nl 15-60), WBC 220 lymphocyte-predominant, RBC 45, opening pressure 180. Diagnosis?", a: "HSV encephalitis - a hemorrhagic necrotizing encephalitis of the frontal and medial temporal lobes. RBCs in the CSF (>4-49/mm3 in an infective setting) are highly characteristic; temporal lobe hemorrhage may show on CT/MRI but imaging can be negative; EEG shows temporal complexes/slowing. Exceedingly HY. CSF patterns: bacterial = opening pressure >200 (90%), WBC >1000 neutrophils, protein 100-500, glucose <40; viral = normal opening pressure, WBC <100 lymphocytes, protein <95, normal glucose; fungal = OP rises with fungal burden, WBC 10-500 lymphocytes, protein 20-150, decreased glucose; TB = OP up ~half the time, WBC 100-500 lymphocytes, protein 100-500, decreased glucose." },
  // ===== MICRO: Influenza =====
  { id: "mic10", category: "Influenza", q: "12F with 3 days of fever, sore throat, chills, myalgias, malaise - preventable by a yearly vaccine designed to induce an antibody response to a protein that binds sialic acid residues. Best description of the virus (genome / envelope / sense / segmentation)?", a: "RNA; enveloped; negative-sense; segmented - influenza. Hemagglutinin binds sialic acid residues on cell-surface glycoproteins/glycolipids to begin infection; neuraminidase cleaves sialic acid so new virions don't reinfect the same cell. Current vaccines induce anti-hemagglutinin antibodies. Killed (IM) vaccine: anyone >6 months, including pregnant women. Live-attenuated (intranasal): non-pregnant, non-immunocompromised, age 2-49." },
  // ===== MICRO: Rabies =====
  { id: "mic11", category: "Rabies", q: "15M in Vermont is bitten by an injured raccoon; two months later - severe headache, paresthesia of the bitten hand, fever, hypersalivation, hydrophobia, aerophobia; dies the same day. Best description of the causative organism (genome / envelope / sense / segmentation)?", a: "RNA; enveloped; negative-sense; non-segmented - rabies, a bullet-shaped virus with neuronal tropism. The slide shows a Negri body: sharply demarcated eosinophilic inclusions in hippocampal pyramidal cells, cerebellar Purkinje cells, and brainstem nuclei. Raccoons are the most common US east coast reservoir. Virus ascends 12-14 mm/day to the spinal ganglion (rapid replication there causes paresthesia at the bite site - pathognomonic, ~half of cases), then 200-400 mm/day to brain and salivary glands, binding ACh, GABA, and glycine receptors. Incubation 20-60 days; hydrophobia and aerophobia are pathognomonic. HY: post-exposure for the UNVACCINATED = immunoglobulin + 4 vaccine doses (days 0, 3, 7, 14); previously vaccinated = no immunoglobulin, 2 doses (days 0, 3); pre-exposure (vets, handlers, spelunkers, travelers) = 3 doses (days 0, 7, 21/28).", img: "/qimg/micro/negri-body.webp", alt: "Negri body: sharply demarcated eosinophilic intracytoplasmic inclusion within a neuron - classic histopathology of rabies" },
  // ===== MICRO: Hepatitis =====
  { id: "mic12", category: "Hepatitis", q: "30M with 2 weeks of fever, body pain, vomiting after recent IV drug use and unprotected sex; anti-HCV positive, PCR detects HCV RNA genotype 3. Most likely mechanism of hepatocellular injury?", a: "T cell-mediated hepatocellular apoptosis. For hepatitis C the evidence favors immune-mediated damage, not direct viral cytotoxicity: CD95L-positive T lymphocytes interact with CD95-bearing hepatocytes, driving apoptosis. Hepatitis A, B, and E injury is also immune-mediated; hepatitis D is the contrast - it may cause DIRECT viral cytotoxicity. Also HY: HCV spreads via contaminated blood/IVDU (single needle-stick risk 5-15%); sexual transmission risk is reassuringly low (~1 per 190,000-380,000 contacts)." },
  // ===== MICRO: RSV =====
  { id: "mic13", category: "RSV", q: "4-month-old girl with 2 days of fever 101F; well-appearing, no rash, soft expiratory crackles across both lung fields. Most appropriate treatment?", a: "Supportive care only (fluid replenishment, oxygen if needed) - this is RSV bronchiolitis, the most common cause of bronchiolitis in infants (peak 2-3 months; 50-90% of hospitalized bronchiolitis; two-thirds of infants infected by age 1). Ribavirin is the only FDA-approved drug but should NOT be used routinely (cost + side-effect profile) - it is the wrong answer on the USMLE. Palivizumab (anti-RSV F-protein monoclonal) is prophylaxis only, never treatment - indicated for preterm neonates <35 weeks or congenital heart/lung disease. Motavizumab is 20x more potent but not recommended (no safety/efficacy data). Corticosteroids, inhaled or oral, are not indicated." },
  // ===== MICRO: Hepatitis =====
  { id: "mic14", category: "Hepatitis", q: "26F at 34 weeks gestation, 2 weeks after returning from India: severe fatigue, anorexia, abdominal pain, fever 102F, BP 90/60, scleral icterus, palpable liver edge; deteriorates and dies. Best description of the causative pathogen (genome / envelope / strandedness / segmentation)?", a: "RNA; non-enveloped; single-stranded; non-segmented - hepatitis E. Highly prevalent in South Asia, especially India; causes fulminant hepatitis and death in pregnant women (genotype 1; maternal mortality up to 15-25%, worst in the 2nd/3rd trimesters; also PROM, postpartum hemorrhage, spontaneous abortion, intrauterine fetal demise). Mechanism: pregnancy hormones (estrogen/progesterone) downregulate the p65 component of NF-kB and shift toward a CD4+ Th2 response, which doesn't clear virus - CD8+ T cells are required for robust HEV clearance. Incubation 2-10 weeks." },
  // ===== MICRO: CNS Viruses =====
  { id: "mic15", category: "CNS Viruses", q: "16F with 4 days of worsening frontal headache, fevers and rigor, one episode of vomiting, neck pain/stiffness, photophobia; CSF: glucose 55 (nl 50-80), protein 65 (nl 15-60), WBC 90 lymphocyte-predominant, RBC 0-1, opening pressure 180. Diagnosis?", a: "Echovirus - this is viral (aseptic) meningitis, and echovirus is the most common cause. Her CSF fits the viral pattern: normal opening pressure, WBC <100 with lymphocyte predominance, protein <95, normal glucose, and no RBCs (RBCs would point to HSV encephalitis). Photophobia + neck stiffness are highly characteristic of meningitis; aseptic is more common than bacterial. (Same CSF table as the HSV encephalitis card: bacterial = OP >200, WBC >1000 neutrophils, protein 100-500, glucose <40; fungal = OP up with burden, WBC 10-500 lymphocytes, protein 20-150, low glucose.)" },
  // ===== MICRO: Herpesviridae =====
  { id: "mic16", category: "Herpesviridae", q: "6M with this rash and no prior dermatologic history. Most likely diagnosis?", a: "Shingles (herpes zoster) - pediatric shingles is uncommon but HY: it exists. Caused by reactivation of VZV from dorsal sensory or cranial nerve ganglia (super-HY); 1 in 3 people develop zoster in their lifetime, most common in older and immunocompromised patients. Unilateral vesicular rash in a dermatomal distribution that scabs in 7-10 days; preherpetic neuralgia (pain/tingling days before the rash) and postherpetic neuralgia (pain after it). Linked to reduced VZV-specific cell-mediated immunity and reduced NK-cell IFN-gamma secretion. Diagnosis is clinical; Tzanck smear shows multinucleated giant cells. Treatment: oral acyclovir/valacyclovir/famciclovir (IV for disseminated disease in the severely immunocompromised); children under 12 generally get no antivirals. Distractors: herpetic whitlow = HSV of a digit (dental professionals); eczema herpeticum = HSV superinfection ON eczema (requires prior eczema); chickenpox = primary VZV, crops of vesicles at different stages of healing.", img: "/qimg/micro/pediatric-shingles.webp", alt: "Unilateral band-like erythematous vesicular rash in a dermatomal distribution on a child's arm and trunk - herpes zoster" },
  // ===== MICRO: Coxsackie =====
  { id: "mic17", category: "Coxsackie", q: "3F with 2 days of dyspnea with feeding, vomiting, pallor; tachypneic, tachycardic, hypotensive, febrile; eyelid puffiness, hepatomegaly, generalized edema; recent self-resolved runny nose and low-grade fever. The most likely pathogen is also associated with what?", a: "Diabetes mellitus type I. This is dilated cardiomyopathy from coxsackie B myocarditis - myocarditis is a common cause of DCM, most cases are viral, and coxsackie B is the most common in children. Mechanism: DIRECT viral cytotoxicity to myocardium - exceedingly HY because it contrasts with rheumatic fever (Group A Strep), which is type II hypersensitivity. Coxsackie B also precipitates DM1: its p2C protein shares a 6-amino-acid sequence (PEVKEK) with the islet auto-antigen GAD65 (molecular mimicry) and binds HLA-DR3 - the antiviral response simultaneously attacks beta islet cells. Hand-foot-mouth disease (painful vesicles on hands/feet/mouth, age <5) and herpangina (painful enanthem on soft palate/tonsils/posterior oropharynx) are coxsackie A, not B." },
  // ===== MICRO: Derm =====
  { id: "mic18", category: "Derm", q: "21F with these itchy skin findings on her back, gradually increasing in number over a couple of weeks; sexually active; palms and soles normal. Most likely diagnosis?", a: "Pityriasis rosea - an exceedingly HY spot diagnosis. Self-limiting eruption: a herald ('mother') patch - an erythematous, round-to-oval, scaly plaque 2-10 cm with a depressed center and raised border - followed by crops of smaller lesions on the trunk and proximal extremities in a 'Christmas tree' distribution; lasts ~1-8 weeks (avg 5), then self-resolves; ~half of cases are preceded by a URI-like illness; peak incidence age 20-29. Etiology: strongly associated with HHV6/7, particularly HHV7 reactivation. Distractors: tinea versicolor = Malassezia furfur, hypopigmented patches, topical selenium; nummular eczema = coin-shaped patches, topical steroids; seborrheic dermatitis = Pityrosporum ovale, greasy scales in folds/hair margins, selenium/ketoconazole shampoo; lichen planus = 6 Ps, hepatitis C association; secondary syphilis = rash INCLUDING palms and soles (spared here).", img: "/qimg/micro/pityriasis-rosea.webp", alt: "Herald patch with crops of smaller oval scaly papules on the back in a Christmas tree distribution - pityriasis rosea" },
  // ===== MICRO: Hepatitis =====
  { id: "mic19", category: "Hepatitis", q: "45M recently arrived from China, immigration physical. Hep B serology: HBcAb IgM positive, HBcAb IgG negative, HBsAg negative, HBsAb negative, HBeAg negative. Most accurate interpretation?", a: "Recently infected and in the window period. Marker logic: HBsAb = immunity (the first marker to check); HBsAg = current infection, acute or chronic; HBeAg = robust infectivity / high replication; HBcAb = actual past or current infection (NEVER positive from vaccination); HBcAb IgM = recent infection (<6 months) and the ONLY marker positive during the window period; HBcAb IgG with HBsAg positive (and IgM negative) = chronic infection. The window period = HBsAg already undetectable while HBsAb has not yet risen - so if the USMLE asks for the most reliable marker during the window period, the answer is HBcAb IgM.", aimg: "/qimg/micro/hbv-serology-chart.webp", alt: "Hepatitis B serology interpretation chart: acute/chronic infection, immune (previous infection or vaccinated), window period (only HBcAb and HBcAb IgM positive), susceptible" },
  // ===== MICRO: Herpesviridae =====
  { id: "mic20", category: "Herpesviridae", q: "52M with HIV, off HAART for 3 months, with new violaceous lesions on his back, trunk, and lower extremities. Best description of the histology of these lesions?", a: "Spindle cell proliferation of lymphatic endothelial cells forming sinuous vascular spaces, with PAS-positive intracellular and extracellular hyaline globules (engulfed erythrocytes) - Kaposi sarcoma, a neoplasm of lymphatic endothelium caused by HHV8 (KSHV). Classic in AIDS and elderly men of Ashkenazi Jewish descent; grossly violaceous macules that progress to plaques, papules, then nodules. Distractor histology: lichen planus = basal cell vacuolization + band-like lymphocytic infiltrate at the dermo-epidermal junction with Civatte bodies (hepatitis C association); psoriasis = parakeratosis + thickened projections of the prickle cell layer with PMN and lymphocytic infiltrate; eczema = epidermal spongiosis with elongation of intercellular bridges." },

  // ===== Mehlman HY USMLE Review Parts I-IV: microbiology lines (bacteria, fungi, parasites, antimicrobials) =====
  // ===== MICRO: GI Infections =====
  { id: "mic21", category: "GI Infections", q: "Travel + self-limiting watery or brown/green diarrhea?", a: "Traveler's diarrhea = ETEC (heat-labile or heat-stable toxin)." },
  { id: "mic22", category: "GI Infections", q: "Bloody diarrhea + poultry consumption?", a: "Campylobacter jejuni or Salmonella spp." },
  { id: "mic23", category: "GI Infections", q: "Antibiotics (clindamycin, beta-lactam, cephalosporin) + diarrhea?", a: "C. difficile. Dx = stool AB toxin test, not stool culture. Tx = vancomycin, not metronidazole (updated guidelines as of Feb 2018). Fever of 104 + abdominal distension in C. diff = toxic megacolon - laparotomy." },
  { id: "mic24", category: "GI Infections", q: "Bloody diarrhea + travel?", a: "Entamoeba histolytica. Tx = metronidazole + iodoquinol; can give paromomycin." },
  { id: "mic25", category: "GI Infections", q: "Close quarters, military barracks, or cruise ship + watery diarrhea?", a: "Norwalk virus." },
  { id: "mic26", category: "GI Infections", q: "Child <5 years + watery diarrhea?", a: "Rotavirus." },
  { id: "mic27", category: "GI Infections", q: "Which organism causes bloody diarrhea with only a few organisms needed (low infectious dose)?", a: "Shigella." },
  { id: "mic28", category: "GI Infections", q: "Bloody diarrhea + appendicitis-like pain (pseudoappendicitis) in a child?", a: "Yersinia enterocolitica." },
  { id: "mic29", category: "GI Infections", q: "Bloody diarrhea + reactive arthritis in an adult - which organisms?", a: "Y. enterocolitica, Campylobacter, Shigella, Salmonella." },
  { id: "mic30", category: "GI Infections", q: "Diarrhea followed by Guillain-Barre syndrome - which organism, and what are the GBS CSF findings?", a: "Campylobacter. GBS CSF = albuminocytologic dissociation (high protein + normal cells); Dx = electromyography + nerve conduction studies (on NBME)." },
  { id: "mic31", category: "GI Infections", q: "Vomiting a few hours after eating meat?", a: "S. aureus preformed heat-stable toxin. Same answer for custards, creams, potato salad - the type of food 'wins' over weird findings like bloody diarrhea, because the bloody-diarrhea gram-negative rods (EHEC, Yersinia enterocolitica, Campylobacter, Shigella, Salmonella) have a ~1-3-day incubation. Sick on the scale of hours from food = S. aureus preformed toxin." },
  { id: "mic32", category: "GI Infections", q: "'Hot feels cold; cold feels hot' (temperature dysesthesia)?", a: "Ciguatera toxicity - toxin blocks sodium channels; caused by consumption of reef fish (mahimahi, Spanish mackerel, etc.)." },
  // ===== MICRO: Pneumonia =====
  { id: "mic33", category: "Pneumonia", q: "Community-acquired pneumonia + bilateral CXR infiltrates?", a: "Mycoplasma. Contrast: CAP + lobar pattern (right-lower-lobe consolidation + dullness to percussion) = Strep pneumo; but if they say 'interstitial' in the vignette, answer Mycoplasma, not S. pneumo." },
  { id: "mic34", category: "Pneumonia", q: "Empiric Tx for community-acquired pneumonia?", a: "Azithromycin. If the patient was on antibiotics in the past three months - fluoroquinolone over azithromycin." },
  { id: "mic35", category: "Pneumonia", q: "Pneumonia in a CF patient: which organism under age 10 versus over 10?", a: "Under 10: S. aureus exceeds Pseudomonas. Over 10: Pseudomonas exceeds S. aureus." },
  { id: "mic36", category: "Pneumonia", q: "Pneumonia after influenza infection?", a: "The USMLE wants S. aureus." },
  { id: "mic37", category: "Pneumonia", q: "Pneumonia + rabbits? + cattle? + birds?", a: "Rabbits = F. tularensis. Cattle = Coxiella (Q fever). Birds = Chlamydia psittaci." },
  { id: "mic38", category: "Pneumonia", q: "Aspiration pneumonia or pulmonary abscess - which antibiotic?", a: "Clindamycin." },
  { id: "mic39", category: "Pneumonia", q: "Cups and cups of foul-smelling sputum in a COPD, TB, or CF patient?", a: "Bronchiectasis. Most common cause: worldwide = TB; in western countries = CF." },
  { id: "mic40", category: "Pneumonia", q: "HIV patient with LOBAR pneumonia - PJP or S. pneumo?", a: "Strep pneumo. PJP presents as bilateral interstitial infiltrates + ground-glass appearance on CXR; S. pneumo is lobar. Trick Q like asbestos (bronchogenic carcinoma still beats mesothelioma) - S. pneumo is still more common than PJP in immunocompromised patients. The key is lobar vs bilateral. Dx of PJP pneumonia = bronchoalveolar lavage." },
  { id: "mic41", category: "Pneumonia", q: "Moves into a new apartment, uses the hot tub a lot + low O2 sats + dyspnea + crackles at lung bases, no wheezing, low-grade fever?", a: "Hot tub lung (yes, an actual NBME answer) - caused by hot tub fumes; NOT related to Pseudomonas (that's hot tub folliculitis)." },
  // ===== MICRO: ENT =====
  { id: "mic42", category: "ENT", q: "Most common cause of otitis media, and its treatment?", a: "Strep pneumo. Tx = oral amoxicillin only; amoxicillin/clavulanate (Augmentin) is the wrong answer initially - use it for recurrent OM." },
  { id: "mic43", category: "ENT", q: "Most common cause of otitis externa, and its treatment?", a: "Pseudomonas. Tx = topical ciprofloxacin + hydrocortisone drops." },
  { id: "mic44", category: "ENT", q: "Tx for Strep pharyngitis?", a: "Amoxicillin or penicillin only (not Augmentin)." },
  { id: "mic45", category: "ENT", q: "Kid with very high lymphocytes - which two diagnoses?", a: "ALL or pertussis (weird because pertussis is bacterial, but lymphocytes are often >30k)." },
  // ===== MICRO: Skin + Soft Tissue =====
  { id: "mic46", category: "Skin + Soft Tissue", q: "Most likely organism causing impetigo, and treatment?", a: "S. aureus now exceeds Group A Strep for non-bullous ('regular') impetigo; for bullous, S. aureus has always exceeded S. pyogenes. Tx = topical mupirocin. Golden crusty lesions around the mouth in a school-age child = impetigo, not HSV." },
  { id: "mic47", category: "Skin + Soft Tissue", q: "Sharply demarcated fiery red lesion (e.g., knee to ankle) + fever 101F - diagnosis and most common organism?", a: "Erysipelas - infection of the superficial dermis +/- dermal lymphatics; its superficial nature gives it a well-demarcated, fiery appearance, whereas cellulitis is hypodermis and more diffuse/pink. Most common organism: Group A Strep far exceeds S. aureus. Most common organism for cellulitis: S. aureus exceeds Group A Strep." },
  { id: "mic48", category: "Skin + Soft Tissue", q: "Treatment for erysipelas + cellulitis?", a: "Oral dicloxacillin or oral cephalexin - both cover Staph + Strep; penicillin only covers Strep. Inpatient equivalent: stat IV flucloxacillin or IV cefazolin." },
  { id: "mic49", category: "Skin + Soft Tissue", q: "17M with cellulitis getting worse while holding the amoxicillin canister he got from his GP - what's going on?", a: "Improper antibiotic treatment - he should have received oral dicloxacillin or oral cephalexin; his cellulitis must have been caused by Staph, not Strep." },
  { id: "mic50", category: "Skin + Soft Tissue", q: "Why doesn't amoxicillin or penicillin cover Staph?", a: "Most community Staph (MSSA, not just MRSA) produces beta-lactamase, so you must give a beta-lactamase-resistant beta-lactam. Dicloxacillin/flucloxacillin resist via steric hindrance; nafcillin/oxacillin are typically used for osteomyelitis; 6 weeks of nafcillin is classic for confirmed MSSA endocarditis." },
  { id: "mic51", category: "Skin + Soft Tissue", q: "Severe skin infection involving fascial planes + cutaneous crepitus - organism and treatment?", a: "Clostridium perfringens causing necrotizing fasciitis (polymicrobial, but C. perfringens causes the gas gangrene leading to cutaneous emphysema/crepitus). Tx = surgical debridement + IV broad-spectrum Abx with anaerobic coverage. Perineal gangrene in a 50M diabetic = Fournier gangrene - surgical debridement." },
  { id: "mic52", category: "Skin + Soft Tissue", q: "Tx of MRSA skin infection?", a: "Clindamycin, TMP/SMX, doxycycline, or linezolid - vancomycin has poor skin penetration." },
  { id: "mic53", category: "Skin + Soft Tissue", q: "Hypopigmentation on the upper back/trunk?", a: "Tinea versicolor (Malassezia furfur). Tx = topical selenium." },
  // ===== MICRO: Fungal =====
  { id: "mic54", category: "Fungal", q: "Tinea treatments: capitis, onychomycosis, pedis, corporis?", a: "Tinea capitis = oral griseofulvin for the patient only (decrease risk by not sharing hats). Onychomycosis (nailbed fungus) = oral terbinafine. Tinea pedis = topical terbinafine or topical azole. Tinea corporis (ringworm) = topical azole (clotrimazole or miconazole)." },
  { id: "mic55", category: "Fungal", q: "Candida treatments: cutaneous, oropharyngeal, esophageal, vaginal?", a: "Cutaneous candida = oral azole. Oropharyngeal candida = nystatin mouthwash. Esophageal candidiasis = oral azole, NOT nystatin mouthwash. Vaginal candidiasis = topical nystatin before trying oral azole." },
  { id: "mic56", category: "Fungal", q: "CNS fungal infection or fungemia (rigors/chills) - treatment?", a: "Amphotericin B. Simple fungal pneumonia = fluconazole." },
  { id: "mic57", category: "Fungal", q: "Cryptococcal meningitis - diagnosis and treatment?", a: "Dx = latex agglutination if listed over India ink; mucicarmine staining (red stain) can also be done. Tx = amphotericin B + flucytosine, followed by a fluconazole taper." },
  { id: "mic58", category: "Fungal", q: "Rose thorn + finger papule - organism and treatment?", a: "Sporothrix schenckii - itraconazole." },
  { id: "mic59", category: "Fungal", q: "Nodular density in the upper lobe in an immunocompromised patient?", a: "Aspergilloma - next best step = open lung biopsy (sounds radical, but it's the NBME answer). Tx with an -azole; invasive aspergillosis can be treated with caspofungin or voriconazole." },
  // ===== MICRO: Meningitis =====
  { id: "mic60", category: "Meningitis", q: "Empiric antibiotic therapy for meningitis, and LP or Abx first?", a: "Ceftriaxone + vancomycin (+/- steroids). New guidelines say LP first. Do a CT head before LP when there's confusion that interferes with the neurologic exam / decreased GCS." },
  { id: "mic61", category: "Meningitis", q: "CSF in bacterial vs aseptic (viral) vs fungal meningitis?", a: "Bacterial: low glucose, high protein, high neutrophils (PMNs). Aseptic (viral): normal glucose, normal or slightly elevated protein, high lymphocytes. Fungal: low glucose, high protein, high lymphocytes (similar to bacterial, but lymphocytes instead of neutrophils)." },
  { id: "mic62", category: "Meningitis", q: "Meningitis vs encephalitis?", a: "Meningitis = nuchal rigidity (neck stiffness) + photophobia + ophthalmoplegia. Encephalitis presents with confusion." },
  // ===== MICRO: UTI + Renal =====
  { id: "mic63", category: "UTI + Renal", q: "Prostatitis treatment - and the drug class mechanism?", a: "Ciprofloxacin - fluoroquinolones inhibit DNA gyrase / topoisomerase II." },
  { id: "mic64", category: "UTI + Renal", q: "Costovertebral angle tenderness + fever - diagnosis and treatment?", a: "Pyelonephritis. Tx = ciprofloxacin, OR ampicillin + gentamicin." },
  { id: "mic65", category: "UTI + Renal", q: "Tx of UTI? Tx of cystitis?", a: "UTI = TMP/SMX or nitrofurantoin. Cystitis = nitrofurantoin (need not be pregnant)." },
  { id: "mic66", category: "UTI + Renal", q: "19F + alkaline urine + renal tract calculi - which organism?", a: "Proteus (Klebsiella or Serratia also acceptable) - struvite (ammonium magnesium phosphate) stones form in alkaline urine secondary to UTIs caused by urease-positive organisms." },
  // ===== MICRO: Endocarditis + Rheumatic =====
  { id: "mic67", category: "Endocarditis + Rheumatic", q: "New-onset murmur + fever?", a: "Endocarditis till proven otherwise. Empiric Tx = vancomycin or ampicillin/sulbactam, PLUS gentamicin." },
  { id: "mic68", category: "Endocarditis + Rheumatic", q: "Rheumatic heart disease acutely (onset of Group A Strep infection) - which valve lesion?", a: "Mitral regurgitation." },
  { id: "mic69", category: "Endocarditis + Rheumatic", q: "Infective causes of third-degree heart block?", a: "Lyme disease, congenital lupus, diphtheria." },
  // ===== MICRO: Sepsis + Shock =====
  { id: "mic70", category: "Sepsis + Shock", q: "Preferred antibiotic in sepsis? In young children? In spontaneous bacterial peritonitis?", a: "Sepsis = ceftriaxone. Young children = cefotaxime. Spontaneous bacterial peritonitis = ceftriaxone." },
  { id: "mic71", category: "Sepsis + Shock", q: "Tx for febrile neutropenia / neutropenic fever?", a: "Immediate broad-spectrum IV antibiotics - e.g., piperacillin/tazobactam, or cefepime + vancomycin." },
  { id: "mic72", category: "Sepsis + Shock", q: "In septic shock, what does LPS bind, and how is that different from toxic shock syndrome?", a: "Endotoxic shock: lipid A of LPS binds CD14 on macrophages (Toll-like receptor 4; TLR-4) - macrophages release TNF-alpha and IL-1. Toxic shock syndrome: S. aureus TSST toxin (a superantigen) bridges MHC-II and TCR, causing cytokine release. If the Q mentions cotton nasal packing or tampons - choose the MHC-II + TCR combo, not CD14/TLR-4." },
  // ===== MICRO: Bone + Joint =====
  { id: "mic73", category: "Bone + Joint", q: "Any patient with a red, warm, tender knee - next step, and the biggest risk factor for septic arthritis?", a: "Joint aspiration (arthrocentesis) - septic arthritis till proven otherwise. Biggest risk factor = abnormal joint architecture." },
  { id: "mic74", category: "Bone + Joint", q: "Tx of osteomyelitis?", a: "IV nafcillin or IV oxacillin or IV cefazolin; add ceftriaxone in sickle cell; add clindamycin in MRSA." },
  // ===== MICRO: Parasites =====
  { id: "mic75", category: "Malaria", q: "Dx of malaria?", a: "Thick + thin blood smears, not antibody titer for Plasmodium species." },
  { id: "mic76", category: "Malaria", q: "Girl goes to Africa on chloroquine prophylaxis and gets malaria anyway - non-adherence or resistance?", a: "Resistance to chloroquine. MOA of chloroquine = inhibits Plasmodium heme polymerase. Prophylaxis for chloroquine-resistant areas = mefloquine." },
  { id: "mic77", category: "Malaria", q: "Which malaria type is worst and why? Fever cycles per species?", a: "P. falciparum is worst - it causes cerebral malaria. Fever cycles: P. vivax/ovale every 48 hours; P. malariae every 72 hours; P. falciparum sporadic/unpredictable." },
  { id: "mic78", category: "Malaria", q: "Treated with atovaquone + proguanil, presentation subsides, then one month later malaria again - why?", a: "Reactivation of the non-erythrocytic form - she has P. vivax or P. ovale, which cause hypnozoites (intra-hepatic form). Primaquine is given because it kills hypnozoites / extra-erythrocytic forms." },
  { id: "mic79", category: "Malaria", q: "Why does sickle cell confer resistance to malaria?", a: "Decreased RBC lifespan - malaria needs a normal RBC lifespan to complete its life cycle." },
  { id: "mic80", category: "Parasites", q: "Travel + bloody diarrhea + RUQ pain - diagnosis and management?", a: "Liver abscess due to Entamoeba histolytica. Tx = percutaneous drainage BEFORE antibiotics; Abx = metronidazole + iodoquinol (iodoquinol kills the intraluminal parasite); paromomycin may also be given." },
  { id: "mic81", category: "Parasites", q: "Watery diarrhea in an immunocompromised patient?", a: "Cryptosporidium parvum." },
  { id: "mic82", category: "Parasites", q: "Giardia - transmission, classic presentation, treatment?", a: "Transmission = water-borne (not fecal-oral). Steatorrhea in a guy who went swimming or scuba diving = Giardia. Tx = metronidazole." },
  { id: "mic83", category: "Parasites", q: "Fever + periorbital edema + muscle aches + went to a BBQ?", a: "Trichinella spiralis - the classic trichinosis triad. From bear meat (Alaska hunts) or pork - it's a pork NEMATODE, not a cestode." },
  { id: "mic84", category: "Parasites", q: "Nematode vs cestode vs trematode?", a: "Nematode = roundworm; cestode = tapeworm; trematode = fluke." },
  { id: "mic85", category: "Parasites", q: "Cestode (tapeworm) from pork - organism and diseases?", a: "Taenia solium - causes cysticercosis (muscle cysts) and neurocysticercosis (brain cysts)." },
  { id: "mic86", category: "Parasites", q: "'Swiss cheese appearance' of brain, or a single cystic lesion on brain CT in someone who went to Mexico?", a: "Neurocysticercosis. Tx = praziquantel or albendazole (the USMLE will never list both and make you choose - the correct answer will be the only anti-helminth drug listed)." },
  { id: "mic87", category: "Parasites", q: "Which helminth causes visceral larva migrans?", a: "Toxocara canis." },
  { id: "mic88", category: "Parasites", q: "Worm in the eye - organism and vector?", a: "Loa loa - from deer, horse, or mango fly." },
  { id: "mic89", category: "Parasites", q: "27M from Pennsylvania + splenectomy + RBCs show intraerythrocytic rings?", a: "Babesia - causes a malaria-like hemolytic disorder in patients who never left the US; ring forms and Maltese crosses within RBCs. If the Q says the patient went to Africa, choose malaria, not Babesia; if they didn't leave the US, malaria is the wrong answer." },
  { id: "mic90", category: "Parasites", q: "Woman gets toxoplasmosis but cats isn't listed - where did she get it?", a: "Pork - can also be written simply as 'delicatessen meats' (both answers appear on offline NBMEs)." },
  // ===== MICRO: STI + Spirochetes =====
  { id: "mic91", category: "STI + Spirochetes", q: "25M + rash on palms and soles + gets an antibiotic he's received before, then develops fever, tachycardia, tachypnea?", a: "Jarisch-Herxheimer reaction (also written as 'reaction to lysis of spirochetes'). He has secondary syphilis (Treponema pallidum) - the palms/soles rash is the tell. Tx = penicillin G; lysis of spirochetes causes the anaphylaxis-like J-H reaction." },
  // ===== MICRO: Congenital Infections =====
  { id: "mic92", category: "Congenital Infections", q: "Newborn + chorioretinitis + cataracts + microcephaly?", a: "CMV. Congenital toxo is ALWAYS the triad of chorioretinitis + hydrocephalus + intracranial calcifications - without that exact triad, eliminate toxo. Congenital CMV = a nonspecific mix (deafness, chorioretinitis, calcifications). Congenital rubella = PDA. Congenital syphilis = tooth abnormalities (Hutchinson), often saddle nose and/or saber shins. Congenital VZV = zig-zag skin lesions, limb abnormalities, microphthalmia." },
  // ===== MICRO: Antimicrobials =====
  { id: "mic93", category: "Antimicrobials", q: "Tx of CMV - drug, mechanism, toxicity?", a: "Ganciclovir (DNA polymerase inhibitor). Toxicity = neutropenia (mouth ulcers + fever)." },
  { id: "mic94", category: "Antimicrobials", q: "Tx of herpes - drug and toxicity?", a: "Acyclovir. Toxicity = nephrotoxicity (crystal nephropathy - acyclovir stones are not visible on CT)." },
  { id: "mic95", category: "Antimicrobials", q: "Woman who works in dental care with a vesicle on her finger - diagnosis and treatment?", a: "Herpetic whitlow - HSV1/2 of the finger. Treat with ORAL acyclovir (in real life both oral and topical are given; on the USMLE the answer is always oral)." },
  { id: "mic96", category: "Antimicrobials", q: "HY drugs that cause agranulocytosis - and how does it present?", a: "Clozapine, ganciclovir, propylthiouracil, methimazole, methotrexate, ticlopidine. Presents as mouth ulcers + fever." },
  { id: "mic97", category: "Antimicrobials", q: "Cause of vitamin K deficiency in adults?", a: "Chronic antibiotics knock out colonic flora." },
  { id: "mic98", category: "Antimicrobials", q: "Beta-lactam (e.g., nafcillin) or cephalosporin + rash + renal issue?", a: "Interstitial (tubulointerstitial) nephritis - WBCs on dipstick, eosinophils in the urine." },
  // ===== MICRO: Vaccines =====
  { id: "mic99", category: "Vaccines", q: "Killed IM influenza vaccine - when, and is it safe in pregnancy?", a: "Every year in fall/winter only, starting at 6 months of age. Yes - give anytime to pregnant women." },
  { id: "mic100", category: "Vaccines", q: "Live-attenuated intranasal influenza vaccine - guidelines?", a: "Only for age 2-49, non-pregnant, non-immunocompromised persons." },
  { id: "mic101", category: "Vaccines", q: "Which vaccines are given at 2, 4, 6 months?", a: "HepB, polio (Salk), pneumo PCV13, DPT, HiB, rotavirus (HepB is also given at birth)." },
  { id: "mic102", category: "Vaccines", q: "HPV vaccine - what ages?", a: "Age 9-45." },
  { id: "mic103", category: "Vaccines", q: "Mom's HepB status is unknown - what does the neonate get?", a: "HepB vaccine; only give immunoglobulin if mom comes back positive." },
  { id: "mic104", category: "Vaccines", q: "Pneumococcal vaccines at age 65+?", a: "PCV13 followed by PPSV23 6-12 months later." },
  // ===== MICRO: Post-Infectious =====
  { id: "mic105", category: "Post-Infectious", q: "PPD test for TB is which type of hypersensitivity?", a: "Type IV (delayed-type, T cell-mediated) - same family as contact dermatitis (nickel, poison ivy) and MS." },
  { id: "mic106", category: "Post-Infectious", q: "Erythema nodosum - mechanism and the infectious causes the USMLE likes?", a: "Panniculitis (inflammation of subcutaneous fat) from immune complex deposition. USMLE likes Crohn disease, sulfa drugs, Strep infections, and Coccidioidomycosis." },
  { id: "mic107", category: "Post-Infectious", q: "12M + red urine 1-2 weeks after a URTI or skin infection?", a: "PSGN - it can occur after Group A Strep SKIN infections (impetigo, erysipelas, cellulitis), not just pharyngitis." },
  { id: "mic108", category: "Post-Infectious", q: "Super-HY postinfectious arthritis - which infections?", a: "HepB, HepC, rubella, Yersinia." },
  { id: "mic109", category: "Post-Infectious", q: "Cold autoimmune hemolytic anemia - mechanism and classic trigger?", a: "IgM antibodies against RBCs - classically Mycoplasma." },
  { id: "mic110", category: "Post-Infectious", q: "Immunosuppressed patient (e.g., SLE, dermatomyositis) with an irregular ring-enhancing lesion on head CT - toxo or something else?", a: "Primary CNS lymphoma, not toxoplasmosis - autoimmune diseases (and dermatomyositis specifically) increase the risk of non-Hodgkin lymphoma." },
  { id: "mic111", category: "GI Infections", q: "H. pylori duodenal ulcer - classic patient?", a: "A younger immigrant patient (pain 1-2 hours after meals). Contrast: the same pain pattern in a patient with severe cardiovascular history = chronic mesenteric ischemia (atherosclerosis)." },
  // ===== MICRO: Endocarditis + Rheumatic (sweep) =====
  { id: "mic112", category: "Endocarditis + Rheumatic", q: "Acute vs subacute infective endocarditis - patient, valve, organism?", a: "Acute: NO prior valve abnormality; almost always S. aureus; classically an IV drug user (venous inoculation seeds the TRICUSPID valve -> tricuspid regurg). Subacute: prior valve abnormality (congenital bicuspid aortic valve, Hx of rheumatic fever); classically follows dental procedures; caused by Strep viridans (= S. sanguinis / S. mutans), whose limit-dextrin (carbohydrate) production lets it bind the mitral + aortic valves. Either way: new-onset murmur + fever = endocarditis until proven otherwise; unlike rheumatic fever (mere antibody response), this is actual bacterial colonization with vegetations." },
  { id: "mic113", category: "Endocarditis + Rheumatic", q: "What is HACEK, and which endocarditis organism is tied to human bites?", a: "HACEK = gram-negative endocarditis organisms: Haemophilus spp, Aggregatibacter actinomycetemcomitans, Cardiobacterium hominis, Eikenella corrodens, Kingella kingae. Extremely low yield to memorize, but the USMLE likes Eikenella corrodens: associated with HUMAN BITES, grows white, and has a bleach-like odor." },
  { id: "mic114", category: "Endocarditis + Rheumatic", q: "Endocarditis prophylaxis before a dental procedure - who actually gets it on the USMLE?", a: "Almost nobody. Only indications: prosthetic material in the heart, incompletely/unrepaired cyanotic congenital heart disease, or Hx of prior endocarditis. Mere mitral valve prolapse or a small ASD/VSD that never became cyanotic is NOT an indication - if the Q asks whether prophylaxis is indicated, the answer is almost always do not give it." },
  { id: "mic115", category: "Endocarditis + Rheumatic", q: "Libman-Sacks endocarditis - disease association, lesion appearance, valve sequela?", a: "Seen in SLE; 60% of those with it have antiphospholipid antibodies (lupus anticoagulant). Verrucous vegetations on BOTH sides of the mitral valve. Associated with mitral STENOSIS - one of the rare non-rheumatic causes of MS (a 32F with SLE + diastolic rumbling murmur = Libman-Sacks). Contrast marantic (NBTE) endocarditis of malignancy and infective endocarditis with large floppy vegetations." },
  { id: "mic116", category: "Endocarditis + Rheumatic", q: "Rheumatic fever - mechanism, JONES criteria, and why erythema marginatum is the word to remember?", a: "Type II hypersensitivity: antibodies against M-protein of Group A Strep (S. pyogenes) cross-react with the mitral valve (molecular mimicry). JONES: Joints (polyarthritis) + carditis (myocarditis / mitral valve disease) + Nodules (subcutaneous, over bony prominences) + Erythema marginatum (annular, serpiginous) + Sydenham chorea (antibody-mediated destruction of the corpus striatum of the basal ganglia - if a kid with RF gets a movement disorder, the cause is autoimmune). Erythema marginatum is specific to RF - erythema multiforme is the drug-rash one; don't mix them. RF can appear on NBME as early as 2 days after Strep pharyngitis (PSGN takes 1-2 weeks). RF acutely = MR in the child, chronically = MS as the valve scars." },
  { id: "mic117", category: "Endocarditis + Rheumatic", q: "12F with red ('strawberry') tongue + salmon-pink body rash + fever - Dx, organism, and why treat?", a: "Scarlet fever, caused by Group A Strep (S. pyogenes). Give penicillin to PREVENT rheumatic fever. RF comes only from oropharyngeal infection (pharyngitis / scarlet fever = pharyngitis + body rash) - cutaneous Group A Strep infections (impetigo, erysipelas, cellulitis) do NOT cause RF, though they can still cause PSGN." },
  { id: "mic118", category: "Endocarditis + Rheumatic", q: "Cellulitis + BP of 80/40 - which immunologic receptors are bound, and by what?", a: "MHC-II and T-cell receptor - bridged by exotoxin A (erythrogenic toxin) of Strep pyogenes, a superantigen causing massive cytokine release (toxic shock-LIKE syndrome). Contrast classic toxic shock syndrome: S. aureus TSST (same MHC-II/TCR bridge) with cotton nasal packing or tampons in the vignette. If cellulitis is causing shock, the answer is Strep pyogenes - Staph won't be listed." },
  // ===== MICRO: STI + Spirochetes (sweep) =====
  { id: "mic119", category: "STI + Spirochetes", q: "24M with a painless ulcer on his penile shaft - Dx, organism, how to visualize, Tx?", a: "Primary syphilis (chancre). Organism = Treponema pallidum, a spirochete. Visualize with darkfield microscopy; VDRL/RPR can be negative early in primary disease. Tx = penicillin. Do not confuse with chancroid = PAINFUL ulcer caused by Haemophilus ducreyi (Tx = azithromycin). Other spirochetes to know as a family: Leptospira interrogans, Borrelia burgdorferi (Lyme), Borrelia recurrentis (relapsing fever)." },
  { id: "mic120", category: "STI + Spirochetes", q: "Maculopapular/nodular body rash involving palms and soles after unprotected sex (KOH negative) - Dx and how to confirm?", a: "Secondary syphilis. Confirm with serology: VDRL/RPR, followed by fluorescent treponemal antibody (FTA-ABS). Palms/soles involvement is classic but need not be mentioned; wart-like genital lesions (condylomata lata) are also secondary syphilis. The negative KOH is the tell that it's not tinea versicolor. Remember: SLE and antiphospholipid syndrome can cause FALSE-POSITIVE VDRL/RPR." },
  { id: "mic121", category: "STI + Spirochetes", q: "Tertiary syphilis - skin lesion, cardiovascular lesion (with mechanism), and neuro findings?", a: "Gumma is the tertiary skin lesion. Cardiovascular: ascending aortitis with aortic aneurysm (AR murmur) - T. pallidum invades the vasa vasorum, causing endarteritis + obliteration and 'tree-barking' of the aorta. Neurosyphilis can occur at ANY stage (often secondary - even in an 18-year-old): tabes dorsalis = positive Romberg; Argyll Robertson pupil (accommodates but doesn't react). Neurosyphilis is a reversible cause of dementia." },
  { id: "mic122", category: "STI + Spirochetes", q: "7M from Massachusetts with a circular rash on his limb + Bell's palsy - Dx, and Tx for this kid vs an adult vs a pregnant woman?", a: "Lyme disease (Borrelia burgdorferi, Ixodes tick). The rash is erythema chronicum migrans - the classic target, but on USMLE it can merely be circular without central clearing; a non-target circular rash + Bell's palsy = Lyme. Tx: kids <8 and pregnant women = amoxicillin (doxycycline is contraindicated); adults = doxycycline; severe disseminated Lyme (cardiac or CNS involvement) = ceftriaxone - and if a pregnant woman's answer choices force it, ceftriaxone is the flexible pick because doxy can't be given." },
  { id: "mic123", category: "STI + Spirochetes", q: "25M with a tick on his dog + circular rash + smear shows intracellular 'berry cluster' organisms in phagocytes - Dx and vector?", a: "Ehrlichiosis (Ehrlichia chaffeensis) - the berry clusters are morulae. Spread by the Ixodes tick, same vector as Lyme, Babesia, and Anaplasma." },
  { id: "mic124", category: "STI + Spirochetes", q: "24F in Connecticut goes hiking, develops fever + rash spreading from wrists/ankles toward the chest - Dx, organism, Tx?", a: "Rocky Mountain spotted fever (Rickettsia rickettsii). Rash classically starts on the wrists/ankles and spreads centripetally. Tx = doxycycline (age 9+ per Mehlman; pregnant women and younger children get other agents)." },
  // ===== MICRO: Skin + Soft Tissue (sweep) =====
  { id: "mic125", category: "Skin + Soft Tissue", q: "54M diabetic with a red rash in the axilla that glows coral-red under a Wood lamp - Dx and organism?", a: "Erythrasma, caused by Corynebacterium minutissimum - an intertriginous infection that fluoresces coral red under Wood lamp. Contrast tinea (no coral-red glow) and cutaneous Candida (beefy red with satellite lesions in obesity/insulin resistance)." },
  { id: "mic126", category: "Skin + Soft Tissue", q: "56F with poorly controlled diabetes + Pseudomonal sepsis + a black necrotic skin lesion - Dx?", a: "Ecthyma gangrenosum - the uncommon cutaneous infection of severe Pseudomonas infection/sepsis." },
  { id: "mic127", category: "Skin + Soft Tissue", q: "62M poorly controlled diabetic with black necrotic skin on the perineum/scrotum - Dx and most common culprit?", a: "Fournier gangrene - rare perineal/scrotal gangrene of older male diabetics; Clostridium perfringens is the most common culprit. (C. perfringens also causes gas gangrene after penetrating trauma - subcutaneous emphysema/crepitus - and the same organism's enterotoxin causes watery diarrhea food poisoning.)" },
  { id: "mic128", category: "Skin + Soft Tissue", q: "Neonate with diffuse pink body rash + desquamation of palms and soles - Dx and toxin mechanism?", a: "Staphylococcal scalded skin syndrome (SSSS) - epidermolytic (exfoliative) exotoxin of S. aureus (produced by ~5% of community Staph) cleaves desmoglein-1 in desmosomes, splitting the epidermis." },
  { id: "mic129", category: "Skin + Soft Tissue", q: "24M with itchy patches and greasy scales along the hairline - Dx, organism, Tx, and the HIV pearl?", a: "Seborrheic dermatitis (dandruff) - inflammatory response to over-colonization with Malassezia yeast. Tx = topical selenium or ketoconazole shampoo. Unlike tinea capitis it causes no circular alopecia and is more common in adults. High prevalence in HIV - sudden-onset seborrheic dermatitis in an MSM patient = do an HIV test." },
  { id: "mic130", category: "Skin + Soft Tissue", q: "40M in a homeless shelter with itchy 'linear burrows'; topical antifungals failed - Dx, Tx, and the HIV version?", a: "Scabies (Sarcoptes scabiei). Tx = topical permethrin (also the treatment for pediculosis/lice). Disseminated scabies occurs in HIV patients - Tx = oral ivermectin. Lesions can become superinfected with S. aureus." },
  { id: "mic131", category: "Skin + Soft Tissue", q: "7F with a pet cat + papules on her hand + tender lymph node; biopsy organisms visualized with silver stain - Dx and organism? What does the same organism cause in AIDS?", a: "Cat scratch disease, Bartonella henselae (silver stain). In immunocompromised patients it causes bacillary angiomatosis - Kaposi-sarcoma-like vascular lesions (e.g., a kid on chemo for ALL with new skin lesions, answer choices all bacteria)." },
  { id: "mic132", category: "Skin + Soft Tissue", q: "17M high school wrestler with atopy + burning, painful rash + fever - Dx, mechanism, Tx?", a: "Eczema herpeticum - HSV1/2 superimposed on eczema, often self-inoculated from a cold sore to cracked eczematous skin. Tx = oral acyclovir (or valacyclovir). Herpes infection generally can present with fever, lymphadenopathy, and tingling/burning/painful rash (herpetic neuralgia)." },
  { id: "mic133", category: "Skin + Soft Tissue", q: "40F dentist with a painful vesicular lesion on her finger - Dx and Tx (with drug mechanism)?", a: "Herpetic whitlow - HSV1/2 infection of the finger from inoculation off a cold sore; increased prevalence in dentists/hygienists. Tx = acyclovir/valacyclovir, a DNA polymerase inhibitor causing chain termination." },
  // ===== MICRO: GI Infections (sweep) =====
  { id: "mic134", category: "GI Infections", q: "Traveler with 'liters and liters' of high-volume watery stool (specks of mucus) - Dx and toxin MOA?", a: "Cholera (Vibrio cholerae). 'Rice-water stool' is buzzwordy but rarely written; they describe specks of mucus in high-volume watery stool. Cholera toxin has the SAME mechanism as ETEC heat-labile toxin: ADP-ribosylation locks G-alpha-s on (inhibits its GTPase), increasing adenylyl cyclase activity -> increased cAMP." },
  { id: "mic135", category: "GI Infections", q: "ETEC heat-labile vs heat-stable toxin - second messengers, and which other organisms share each mechanism?", a: "Heat-LABILE toxin -> increased cAMP (via G-alpha-s/adenylyl cyclase) - same mechanism as Vibrio cholerae toxin. Heat-STABLE toxin -> increased cGMP (via guanylyl cyclase) - same mechanism as Yersinia enterocolitica toxin. ETEC = traveler's diarrhea (watery). Incubation for the gram-negative-rod diarrheas (E. coli, Salmonella, Shigella, Yersinia) is 1-3 days." },
  { id: "mic136", category: "GI Infections", q: "Kid with bloody diarrhea + petechiae + red urine - Dx, organisms, and the full toxin mechanism?", a: "Hemolytic uremic syndrome: EHEC O157:H7 (Shiga-like toxin) or Shigella (Shiga toxin). Both toxins inhibit protein synthesis by cleaving the eukaryotic 60S ribosomal subunit; they inflame the renal microvasculature -> ADAMTS13 inactivation -> vWF multimers uncleaved -> platelet aggregation -> shearing of RBCs (schistocytes/helmet cells). HUS = pediatric + bloody diarrhea; TTP = adult with fever + stroke-like symptoms and no bloody diarrhea. Shigella itself can present with seizures on Peds NBME (HUS and 'idiopathic seizure disorder' are wrong answers there)." },
  { id: "mic137", category: "GI Infections", q: "28F recently immigrated from India with fever + rose spots + relative bradycardia ('homeless shelter + diarrhea or constipation') - Dx, organism, reservoir?", a: "Typhoid fever, Salmonella typhi - humans are the only reservoir; classically rose spots on the abdomen. Do NOT confuse with food-poisoning Salmonella (typhimurium, enteritidis): bloody diarrhea 1-3 days after poultry/eggs/reptiles (pet lizard on new NBME). Lab contrast: Salmonella produces H2S gas and is motile with a high infectious dose; Shigella produces no H2S, is non-motile, and needs very few organisms; both are oxidase-negative." },
  { id: "mic138", category: "GI Infections", q: "Traveler with bloody diarrhea + epigastric/RUQ pain - Dx, complication, Tx?", a: "Entamoeba histolytica with liver abscess. Tx = metronidazole (also the treatment for Giardia). The GI protozoa as a group: Entamoeba, Cryptosporidium, Giardia." },
  { id: "mic139", category: "GI Infections", q: "Middle-aged patient with arthritis + diarrhea + malabsorption - Dx and organism?", a: "Whipple disease, caused by the bacterium Tropheryma whipplei. Tx = antibiotics (e.g., doxycycline)." },
  { id: "mic140", category: "GI Infections", q: "Colon cancer is associated with increased risk of endocarditis from which organism?", a: "Strep bovis (S. gallolyticus). Obscure but assessed: colon cancer raises the risk of Strep bovis endocarditis." },
  { id: "mic141", category: "GI Infections", q: "H. pylori treatment regimens?", a: "CAP = Clarithromycin + Amoxicillin + PPI. If penicillin-allergic, swap clarithromycin + amoxicillin for metronidazole + tetracycline + bismuth (keep the PPI)." },
  { id: "mic142", category: "GI Infections", q: "Menetrier disease vs Meniere disease - and the viral association of the gastric one?", a: "Menetrier = giant hypertrophic gastric folds (inner stomach lining resembles brain gyri); can be caused by CMV infection. Meniere = inner ear (vertigo/tinnitus/hearing loss). Don't confuse the names." },
  // ===== MICRO: Parasites (sweep) =====
  { id: "mic143", category: "Parasites", q: "Treatment agents for nematodes, and the odd-one-out use of albendazole?", a: "Most nematodes (Ascaris, Enterobius/pinworm, hookworms): mebendazole (-bendazoles inhibit microtubules/tubulin - an NBME answer) or pyrantel pamoate. Albendazole is the odd one out: preferred for NEUROCYSTICERCOSIS, which is caused by a CESTODE (Taenia solium). Also microtubule inhibitors: vincristine, vinblastine, colchicine, griseofulvin." },
  { id: "mic144", category: "Parasites", q: "Match: intestinal obstruction with rough-surfaced eggs; perianal itching with (+) tape test; eosinophilic meningitis after eating raw slugs/snails.", a: "Ascaris lumbricoides (giant roundworm, ingested, causes intestinal obstruction); Enterobius vermicularis (pinworm - perianal itch, tape test in children); Angiostrongylus (raw slugs/snails -> eosinophilic meningitis)." },
  { id: "mic145", category: "Parasites", q: "Kid walking barefoot on soil/beach + microcytic anemia - Dx, acquisition route, and the other worm acquired the same way?", a: "Hookworm (Ancylostoma duodenale / Necator americanus) - acquired THROUGH THE FEET/skin; sucks blood in the GI tract causing microcytic anemia. Also acquired through skin: Strongyloides stercoralis - larvae travel via blood to the lungs, up the respiratory tree, and are swallowed (intestinal + pulmonary symptoms)." },
  { id: "mic146", category: "Parasites", q: "Match the cestode: fish + high MCV; beef; dogs/travel + liver cysts + diarrhea.", a: "Diphyllobothrium latum (fish tapeworm -> B12 deficiency, macrocytosis); Taenia saginata (beef tapeworm); Echinococcus granulosus (dog/hydatid worm -> hydatid cyst disease of the liver). Pork tapeworm = Taenia solium -> cysticercosis (muscle cysts) + neurocysticercosis ('Swiss cheese' brain / soap-bubble ventricles, classically travel to Mexico)." },
  { id: "mic147", category: "Parasites", q: "Match the trematode: crabmeat + hemoptysis; cholangiocarcinoma; portal hypertension; squamous cell carcinoma of the bladder.", a: "Paragonimus westermani (lung fluke, undercooked crab); Clonorchis sinensis (bile duct cancer); Schistosoma mansoni/japonicum (portal hypertension); Schistosoma haematobium (SCC of the bladder - risk factor is swimming in fresh water in Africa)." },
  { id: "mic148", category: "Parasites", q: "40F back from the Middle East with a skin lesion + elevated LFTs + pancytopenia; transmitted by sandfly - Dx and the eponym?", a: "Leishmaniasis (Leishmania donovani) - a protozoan (unicellular eukaryote) causing visceral disease = kala azar, with increased LFTs and pancytopenia." },
  { id: "mic149", category: "Parasites", q: "9M in Brazil with a black ulcer on his arm, treated with ivermectin - Dx, vector, and its global blindness ranking?", a: "Onchocerciasis (Onchocerca volvulus, river blindness) - spread by black flies. It is the #2 cause of blindness worldwide after trachoma (Chlamydia trachomatis serotypes A-C)." },
  // ===== MICRO: TB + Atypical Myco =====
  { id: "mic150", category: "TB + Atypical Myco", q: "Man on RIPE therapy develops orange sweat and tears - which drug, and the MOA of every TB drug?", a: "Rifampin (orange bodily secretions are benign). MOAs: rifampin = DNA-dependent RNA polymerase inhibitor; isoniazid = mycolic acid synthesis inhibitor; pyrazinamide = fatty acid synthase I inhibitor; ethambutol = arabinosyl transferase inhibitor. TB-drug MOAs are exceedingly HY." },
  { id: "mic151", category: "TB + Atypical Myco", q: "29M from Indonesia with PPD induration of 11 mm and an unremarkable CXR - Dx and management?", a: "Latent TB (positive PPD, negative CXR) - treat with isoniazid + pyridoxine (B6) for 9 months. Algorithm: PPD first (if Hx of BCG vaccine, do IGRA instead - never IGRA + PPD together); measure induration only, erythema doesn't count; repeat a negative PPD once after 1 week (booster reaction); if PPD/IGRA positive -> CXR (never repeat a positive PPD); CXR negative = latent TB prophylaxis; CXR positive = treat active TB." },
  { id: "mic152", category: "TB + Atypical Myco", q: "39M who works at an aquarium with red ulcers/blisters on his hand and arm - Dx?", a: "Mycobacterium marinum - red ulcers on the hand/arm after aquatic exposure (aquarium/waterpark). Do NOT choose Staph aureus when they specifically say aquarium." },
  { id: "mic153", category: "TB + Atypical Myco", q: "Renal transplant patient with a reddish-violaceous preauricular/neck lymph node - organism? Its two classic diseases?", a: "Mycobacterium avium-intracellulare (MAI). Causes lymphadenitis (violaceous neck/preauricular lesion, also in immunocompromised), lung disease in older women (Lady Windermere syndrome), and disseminated disease in AIDS." },
  { id: "mic154", category: "TB + Atypical Myco", q: "45M recently immigrated from Libya (adult chin lesion) - what growth characteristic does the organism have?", a: "Temperature sensitivity - leprosy (Mycobacterium leprae) grows at cooler temperatures, which is why it hits cooler body sites (skin, nose, ears, testes, superficial nerves)." },
  // ===== MICRO: Peds Respiratory (sweep) =====
  { id: "mic155", category: "Pneumonia", q: "6-month-old with runny nose, then a seal-like barking cough - Dx, organism, location, Tx?", a: "Croup (laryngotracheobronchitis) caused by PARAINFLUENZA virus; pathology is in the larynx (subglottic). Tx = supportive; if forced to pick a treatment: steroids, then nebulized racemic epinephrine. Contrast epiglottitis = Haemophilus influenzae type B (unvaccinated/immigrant kids, asplenia/sickle cell risk)." },
  { id: "mic156", category: "Pneumonia", q: "8M recently convalesced from a URTI now has stridor - Dx and usual organism?", a: "Bacterial tracheitis - usually S. aureus; diagnose with bronchoscopy; Tx with a 3rd-gen cephalosporin + aminopenicillin." },
  { id: "mic157", category: "Pneumonia", q: "5F recently convalesced from influenza now has bacterial pneumonia - organism?", a: "Staph aureus - the classic post-influenza bacterial pneumonia organism." },
  { id: "mic158", category: "Pneumonia", q: "6M with lobar pneumonia vs bilateral pneumonia vs lobar with 'interstitial markings' - organisms?", a: "Lobar = Strep pneumoniae (right lower lobe classic). Bilateral = Mycoplasma. Lobar distribution but the stem says 'interstitial markings' and Strep pneumo isn't listed = Mycoplasma - the word 'interstitial' wins. If lobar pneumonia and Strep pneumo isn't an answer choice, pick Staph aureus (Peds NBME). In CF: before age 10 S. aureus exceeds Pseudomonas; after age 10 Pseudomonas eclipses it." },
  { id: "mic159", category: "Pneumonia", q: "3-week-old neonate with pneumonia who had conjunctivitis 1-2 weeks ago - organism and how it got to the lungs?", a: "Chlamydia trachomatis (serotypes D-K, the STD) - drains through the nasolacrimal duct down to the lungs, causing pneumonia with a lymphocytic shift. If a vignette gives neonatal conjunctivitis, chlamydia is always tied to subsequent pneumonia somehow." },
  { id: "mic160", category: "Pneumonia", q: "2M with fever 101F + diffuse crackles across both lungs + mother used IV drugs - Dx?", a: "Pneumocystis jirovecii pneumonia (PJP) in a child with perinatally acquired HIV/AIDS. (Suspect HIV in any infant with PJP.)" },
  { id: "mic161", category: "Pneumonia", q: "3F with 10 days of coughing spells followed by vomiting; her brother has WBCs of 32,000 with 85% lymphocytes - Dx and HY associations?", a: "Pertussis (Bordetella pertussis). Coughing paroxysms + post-tussive emesis; HY associations: absurdly high lymphocyte-predominant WBC count (can mimic ALL) and hypoglycemia. The ALL distinction: pertussis has cough/post-tussive vomiting/hypoglycemia." },
  { id: "mic162", category: "Pneumonia", q: "9M with a grey pseudomembrane in the oropharynx - Dx and Tx?", a: "Diphtheria - Tx = diphtheria antitoxin. Also know diphtheria as an infective cause of third-degree heart block (with Lyme disease and congenital lupus)." },
  { id: "mic163", category: "ENT", q: "Bullous myringitis - organisms?", a: "Classically Mycoplasma (or Strep pneumo). Contrast: otitis externa = Pseudomonas (Tx = topical ciprofloxacin + hydrocortisone; prevention for swimmers/crew = alcohol-acetic acid drops); necrotizing ('malignant') otitis externa with black skin on the ear = Pseudomonas in diabetics; mastoiditis = untreated otitis media (pinna displaced up/out)." },
  // ===== MICRO: Congenital Infections (sweep) =====
  { id: "mic164", category: "Congenital Infections", q: "Neonate with microphthalmia + limb deformities + zig-zag (cicatricial) skin lesions - Dx?", a: "Congenital varicella syndrome. Contrast the others: toxoplasmosis = triad of chorioretinitis + hydrocephalus + intracranial calcifications; rubella = PDA +/- deafness +/- cataracts (a cardiac murmur points away from toxo/CMV); CMV = 'blueberry muffin' rash + periventricular calcifications + deafness (diagnosed by eliminating the others); congenital syphilis = saddle nose, saber shins, Hutchinson/mulberry molars, deafness, cataracts." },
  { id: "mic165", category: "Congenital Infections", q: "HIV-positive mother delivers - what is given to the neonate, when, and what about delivery/breastfeeding?", a: "Zidovudine (AZT) to the neonate within 6-12 hours of birth, continued for 6 weeks. Mother: HAART is always 3-drug therapy; avoid efavirenz (NNRTI) in pregnancy; avoid TMP/SMX in the first trimester (OK in 2nd/3rd); intrapartum zidovudine + C-section. HIV is present in breast milk - avoid breastfeeding even if viral load is undetectable on HAART." },
  // ===== MICRO: Hepatitis (sweep) =====
  { id: "mic166", category: "Hepatitis", q: "Hepatitis A - transmission, chronicity, taxonomy, epidemiology?", a: "Fecal-oral; causes ACUTE hepatitis only (like Hep E; B, C, D can go chronic). RNA virus, Picornaviridae (shared with polio, coxsackie, echovirus). The most common cause of acute hepatitis in the USA and Mexico. Vaccinate MSM (an NBME answer with an otherwise-healthy MSM vignette). Hepatocellular damage in hepatitis generally is due to cytotoxic T lymphocytes (T-cell-mediated apoptosis), NOT direct viral cytopathic effect; hepatitis classically has ALT > AST in the hundreds-thousands (both ~1200 with ALT >= AST = viral hepatitis, not alcoholic)." },
  { id: "mic167", category: "Hepatitis", q: "Hep B - virus structure, polymerase, vaccine schedule, and management of a neonate born to an HBsAg-positive mother?", a: "DNA, enveloped, CIRCULAR (contrast Herpesviridae = DNA, enveloped, LINEAR - a USMLE favorite). Its polymerase has dual function: DNA-dependent DNA polymerase + RNA-dependent DNA polymerase (reverse transcriptase). Vaccine at birth, 2 months, 6 months (no longer 4). Neonate of a positive mother: give HepB vaccine + HBIG within 12 hours - do not wait for the mother's status. If a vaccinated patient shows susceptibility on titers, just give more vaccine (waning immunity). Most common hepatitis worldwide (USMLE likes China)." },
  { id: "mic168", category: "Hepatitis", q: "Hep C - why no vaccine, diagnosis, and US epidemiology?", a: "No vaccine because of massive antigenic variation (>7 genotypes, 80 subtypes). Dx = ELISA + serum HCV RNA levels. Most common hepatitis in the USA." },
  { id: "mic169", category: "Hepatitis", q: "Hep D - what does it need to infect, and how do you prevent it?", a: "Hep D (delta virus, RNA) is a 'subviral satellite': it requires Hep B to infect (co-infection or superinfection) - three HepB proteins form the envelope around it. Prevention = vaccinate against Hep B; there is no HepD vaccine. It has the highest mortality rate of the hepatitis viruses (~20%)." },
  // ===== MICRO: Antimicrobials (sweep) =====
  { id: "mic170", category: "Antimicrobials", q: "Antifungal mechanisms: azoles, terbinafine, nystatin/amphotericin B, echinocandins, griseofulvin - and which for which infection?", a: "Azoles inhibit 14-alpha-demethylase (ergosterol synthesis; ergosterol = the cholesterol equivalent in fungi) - oral fluconazole for candidal ESOPHAGITIS. Terbinafine inhibits squalene epoxidase (lanosterol -> ergosterol) - topical for tinea pedis, oral for onychomycosis. Nystatin and amphotericin B create pores in the ergosterol membrane - nystatin/azoles topical for oropharyngeal thrush; amphotericin B only for very sick patients (fungemia/CNS: high fever + rigors). Echinocandins (caspofungin) inhibit 1,3-beta-glucan synthesis - invasive aspergillosis when voriconazole fails. Griseofulvin inhibits microtubules - oral for tinea capitis." },
  { id: "mic171", category: "Antimicrobials", q: "IV drug user started on empiric endocarditis therapy develops severe oliguria + dark urine - drug, mechanism, toxicities?", a: "Gentamicin (an aminoglycoside) causing acute tubular necrosis; aminoglycosides also cause ototoxicity. Mechanism: bind the 30S ribosomal subunit, inhibiting formation of the initiation complex and causing misreading of mRNA. Empiric endocarditis = gentamicin PLUS vancomycin or ampicillin/sulbactam (add rifampin for prosthetic valves). 50S contrast: chloramphenicol + clindamycin block peptidyl transferase; macrolides block the nascent-peptide tunnel without blocking peptidyl transferase; linezolid-type binding prevents initiation-complex formation at 23S." },
  { id: "mic172", category: "Antimicrobials", q: "57M with Hep C on treatment: total bili 3.3, direct 0.2, retics 9.1%, Hct 38.5 - which drug, its MOA, and the other Hep B/C agents to know?", a: "Ribavirin - an RNA polymerase inhibitor that causes HEMOLYTIC ANEMIA (indirect hyperbilirubinemia + high retics). Also know: sofosbuvir = HCV NS5B nucleotide polymerase inhibitor; glecaprevir = HCV NS3/4A protease inhibitor (hemolysis only if combined with ribavirin); entecavir = DNA polymerase inhibitor for Hep B; ritonavir = HIV protease inhibitor and P-450 inhibitor used as a 'booster' - not associated with hemolysis." },
  { id: "mic173", category: "Antimicrobials", q: "Antigenic shift vs antigenic drift - mechanisms and clinical consequence?", a: "Shift = reassortment of whole segments between two influenza strains (e.g., avian + human) -> highly novel virus capable of pandemics. Drift = point mutations in hemagglutinin or neuraminidase -> milder epidemics. (Viral recombination = coinfection yielding progeny with some genes from each virus - any genes, not whole segments.)" },
  // ===== MICRO: Eye Infections =====
  { id: "mic174", category: "Eye Infections", q: "Neonatal conjunctivitis timing: chemical vs gonococcal vs chlamydial - and prophylaxis/treatment?", a: "Chemical: within the first day(s), classically from silver nitrate drops (replaced by erythromycin ointment for prophylaxis). Gonococcal: within the first week of life. Chlamydial: AFTER the first week (>1 week post-birth), always tied to subsequent pneumonia; prophylaxis = treat the infected mom during pregnancy; treatment of the neonate = ORAL erythromycin (topical is wrong) - and know oral erythromycin is the motilin-agonist association with infantile pyloric stenosis. Allergic conjunctivitis = cobblestoning (kids/adults); viral = teary red eye, adenovirus most common." },
  { id: "mic175", category: "Eye Infections", q: "6M with an itchy eye + infraorbital vesicles + dendritic pattern on fluorescein - Dx and Tx?", a: "Herpes (HSV) keratitis - dendritic (tree-like) pattern on fluorescein instillation. Herpes zoster ophthalmicus (VZV) causes a similar dendritic keratitis. Tx = topical +/- oral acyclovir/valacyclovir. Blurry vision in a severely immunocompromised (AIDS) patient = CMV retinitis." },
  { id: "mic176", category: "Eye Infections", q: "8M with a recent sinus infection now has a red, swollen eye with restricted eye movements and proptosis - Dx, organism, and how it differs from pre-septal cellulitis?", a: "Orbital cellulitis - infection posterior to the orbital septum, most commonly S. aureus spreading from the paranasal sinuses; a medical emergency requiring IV antibiotics. Pre-septal cellulitis is the less severe one: no ophthalmoplegia, no proptosis. 'Orbital = looks like the kid got hit with a softball.'" },
  // ===== MICRO: Misc Viral (sweep) =====
  { id: "mic177", category: "Viral Exanthems", q: "Measles - the pathognomonic spot, what the 3Cs do NOT prove, and the late CNS complication?", a: "Koplik spots (whitish lesions on the buccal mucosa) are pathognomonic. Cough/coryza/conjunctivitis is NOT unique to measles - a simple head-to-toe maculopapular rash with the 3Cs can still be rubella; rubella's unique tell is suboccipital/post-auricular lymphadenopathy. Late complication: subacute sclerosing panencephalitis (reactivation of latent CNS infection in teenagers). Tx supportive; immigrant history can imply unvaccinated." },
  { id: "mic178", category: "Viral Exanthems", q: "6M with vesicles on the palms, soles, and in the posterior oropharynx - Dx, virus, taxonomy?", a: "Hand-foot-mouth disease and/or herpangina, caused by Coxsackie A: RNA, non-enveloped, non-segmented. Herpangina = posterior oropharyngeal vesicles; it can occur with or without hand-foot-mouth. Don't confuse with HSV primary infection (fever + oropharyngeal vesicles in an adult). Coxsackie B is the other one: DCM, pleurodynia, type I DM precipitant (molecular mimicry)." },
  { id: "mic179", category: "Viral Exanthems", q: "Mumps - classic triad, taxonomy, and two extra USMLE uses?", a: "POM = Parotitis, Orchitis, Meningitis (no rash). RNA, enveloped, non-segmented (paramyxovirus). Also: a cause of pancreatitis on USMLE, and the HY cause of orchitis in unvaccinated/immigrant patients (otherwise epididymitis/orchitis bugs = Chlamydia in young men, E. coli in older men; if no organisms grow on culture, choose Chlamydia)." },
  { id: "mic180", category: "Viral Exanthems", q: "EBV mononucleosis - why it gets misread as Strep, the beta-lactam rash, and the test?", a: "EBV is the odd virus out that presents with all four CENTOR criteria (fever, tonsillar exudates, cervical lymphadenopathy, no cough), so it's frequently misdiagnosed as Strep pharyngitis. Giving amoxicillin/penicillin causes an intense pruritic maculopapular rash 7-10 days later on extensor surfaces + pressure points (hypersensitivity in the setting of antiviral antibody production) - not the mild rash EBV itself can cause. Test = heterophile antibody (Monospot). Mono is usually EBV but can be CMV. Also: oral hairy leukoplakia looks like leukoplakia but is caused by EBV (HIV patients)." },
  { id: "mic181", category: "Herpesviridae", q: "84M with sudden-onset Bell's palsy + vesicles around the ear - Dx, eponym, virus?", a: "Herpes zoster oticus = Ramsay Hunt syndrome (type II) - shingles of the facial nerve caused by VZV (HHV3), NOT HSV1/2. ('Herpes zoster' is just another name for shingles; it is not a virus name.) Contrast Lyme Bell's palsy: target-ish rash in an endemic area. Varicella = crops of vesicles at different stages of healing." },
  // ===== MICRO: Sepsis + Shock (sweep) =====
  { id: "mic182", category: "Sepsis + Shock", q: "3M with fever 103F + stiff neck + low BP + non-blanching purpuric rash - organism, the adrenal syndrome, and its physiology?", a: "Neisseria meningitidis (gram-negative diplococci) causing meningitis + meningococcemia. Waterhouse-Friderichsen syndrome = bilateral hemorrhagic necrosis of the adrenal cortices from meningococcal septicemia -> low aldosterone + low cortisol -> refractory hypotension (give normal saline, then hydrocortisone)." },
  { id: "mic183", category: "Sepsis + Shock", q: "Neonate born at term with fever + high WBCs (65% neutrophils, low lymphocytes) - Dx, and the right vs wrong empiric Abx?", a: "Group B Strep (Strep agalactiae) sepsis. Tx = ampicillin + gentamicin (or ampicillin + cefotaxime); vancomycin + ceftriaxone is WRONG on the NBME for GBS. GBS is also the usual cause of neonatal meningitis (gram-positive cocci); if they say gram-negative rods instead, that's E. coli - or Listeria (soft cheese -> stillbirth/granulomatosis infantiseptica; gram-positive rods). Peds empiric meningitis otherwise = cefotaxime + vancomycin (+steroids if confirmed S. pneumo). A neonate born at home with the cord cut by a kitchen knife + lockjaw = tetanus (trismus), Tx = antitoxin." },
  { id: "mic184", category: "Sepsis + Shock", q: "Botulism vs tetanus - toxin targets, presentations, acquisition?", a: "Botulinum toxin (C. botulinum) inhibits presynaptic ACETYLCHOLINE release -> FLACCID paralysis: floppy baby syndrome (spores in honey, infants <1) or CN palsies; adults get pre-formed toxin from canned goods. Tetanus toxin (C. tetani) inhibits release of GABA and glycine (inhibitory transmitters) -> SPASTIC paralysis: trismus (lockjaw) and opisthotonos (arched back); Tx = antitoxin." },
  // ===== MICRO: Post-Infectious (sweep) =====
  { id: "mic185", category: "Post-Infectious", q: "8M with sore throat and a new-onset tic - Dx, mechanism, test?", a: "PANDAS (Pediatric Autoimmune Neuropsychiatric Disorder Associated with Streptococci): Group A Strep pharyngitis can cause new tics/Tourette, OCD, or ADHD in the weeks following infection. Test = anti-streptolysin O titers." },
  { id: "mic186", category: "Post-Infectious", q: "Reactive arthritis - the triad, the classic organism, and which STI does NOT cause it?", a: "Triad: urethritis (or abdominal infection) + polyarthritis + 'eye-itis' (conjunctivitis/episcleritis/anterior uveitis). Classic organism = Chlamydia; gonococcus does NOT cause reactive arthritis. Rubella, Hep B/C, and Yersinia can also cause it." },
  // ===== MICRO: UTI + Renal (sweep) =====
  { id: "mic187", category: "UTI + Renal", q: "16F with thin, grey, watery discharge - Dx, wet-mount finding, Tx?", a: "Bacterial vaginosis (Gardnerella): clue cells on wet mount (squamous cells coated in bacteria) and a fishy odor on KOH whiff test. Tx = topical metronidazole gel. Contrast: white cheese-like discharge = Candida (topical nystatin first, or oral fluconazole); yellow-green = Trichomonas." },
  { id: "mic188", category: "UTI + Renal", q: "16F with mucopurulent discharge + adnexal pain - Dx, Tx, and the liver-capsule extension?", a: "Pelvic inflammatory disease (Chlamydia and/or gonorrhea): Tx = IM ceftriaxone + oral doxycycline (IV antibiotics if septic; treat even if asymptomatic when a partner tests positive). Extension of PID to the liver capsule = Fitz-Hugh-Curtis syndrome. Persistent fever + adnexal pain despite antibiotics = tubo-ovarian abscess." },
  { id: "mic189", category: "Bone + Joint", q: "HPV 6/11 vs 16/18 - diseases, and the airway version in a 2-year-old with stridor?", a: "HPV 6/11 = condylomata acuminata (warts; Tx = podophyllum resin) and laryngeal (respiratory) papillomatosis - a 2F with stridor + small laryngeal growths from maternal vaginal-canal exposure. HPV 16/18 = squamous cell carcinoma of genitalia/anus and oropharynx; risk of overt SCC rises with immunocompromise (HIV in MSM) and heavy smoking. Vaccine ages 9-45." },
];
export default microQuestions;
